// Every run of the study as a plain, serializable specification (PROTOCOL.md §6–§8). The one-at-a-time points, the
// Latin-hypercube neighbourhoods and the 19 cost scenarios are generated by the completed B4/B5 audit's own functions
// and constants (src/b4-b5-robustness/{context,specs}.ts), unchanged: the same distances, legal grid, quantization and
// seed derivation. Generation is deterministic: the same shortlist gives the same list, order and keys.
import { createHash } from 'node:crypto';
import { type BookSpec, dimensionsOf, latinHypercube } from '../b4-b5-robustness/specs.ts';
import { d1Keys } from '../multi-etf-allocator/phenotypes.ts';
import { box as sourceBox } from '../multi-etf-d1/space.ts';
import {
  type CostScenario,
  type OffsetLabel,
  base,
  costScenarios,
  distancesOf,
  incumbentGrid,
  jointSamples,
  jointSeeds,
  jointStream,
  legal,
  offsetLabels
} from './context.ts';
import type { Grid } from './inventory.ts';
import type { Book, Family, Mode, Spec } from './run.ts';

export const modes: Mode[] = ['fixed', 'portfolio'];

// A phenotype under test: an existing source-study vector (research-only) or VGT primary (the registered control).
export interface Phenotype {
  id: string; // e.g. GDX:representative, GDX:alternative-1, VGT-primary
  symbol: string;
  role: string;
  window: 'final' | 'fold-a' | 'fold-b';
  candidateId: string;
  grid: Grid;
  file: string;
  sha256: string;
  researchOnly: boolean;
}

export const vgtPrimary: Phenotype = {
  id: 'VGT-primary',
  symbol: 'VGT',
  role: 'registered control',
  window: 'final',
  candidateId: 'd1-ebc9f639b3',
  grid: { ...incumbentGrid },
  file: 'config/phenotypes/D1/VGT.json',
  sha256: '',
  researchOnly: false
};

export const gridKeyOf = (grid: Grid) => d1Keys.map((key) => grid[key]).join('.');

export const gridLabel = (grid: Grid) =>
  `X ${(grid.targetPercentChange / 10).toFixed(1)}% Y ${(grid.trailingBuyPercentage / 10).toFixed(1)}% stop ${(
    grid.trailingStopPercentage / 10
  ).toFixed(1)}% hold ${grid.maximumHoldDays} L ${grid.tickWindowSize} buffer ${(grid.intradayLossBuffer / 10).toFixed(
    1
  )}% P ${(grid.pullback / 10).toFixed(1)}% W ${grid.continuationWindow}`;

const hashOf = (value: unknown) => createHash('sha256').update(JSON.stringify(value)).digest('hex').slice(0, 16);

// The algorithmic content of a specification (what determines its result).
export const specHashOf = (spec: Spec) =>
  hashOf({
    window: spec.window,
    mode: spec.mode,
    books: spec.books.map((book) => ({ symbol: book.symbol, grid: book.grid })),
    rate: spec.rate,
    costBps: spec.costBps,
    stopSlippageBps: spec.stopSlippageBps,
    stopFill: spec.stopFill,
    boundaryDate: spec.boundaryDate ?? null
  });

export const bookOf = (phenotype: Phenotype, grid: Grid = phenotype.grid): Book => ({
  symbol: phenotype.symbol,
  phenotype: gridKeyOf(grid) === gridKeyOf(phenotype.grid) ? phenotype.id : `${phenotype.id}~diag`,
  grid: { ...grid }
});

export const specOf = (
  fields: Omit<Spec, 'rate' | 'costBps' | 'stopSlippageBps' | 'stopFill' | 'scenario' | 'keepDaily'> & {
    scenario?: CostScenario;
    keepDaily?: boolean;
  }
): Spec => {
  const scenario = fields.scenario ?? costScenarios[0]!;

  return {
    key: fields.key,
    family: fields.family,
    subject: fields.subject,
    window: fields.window,
    mode: fields.mode,
    books: fields.books,
    scenario: scenario.id,
    rate: scenario.rate,
    costBps: scenario.costBps,
    stopSlippageBps: scenario.stopSlippageBps,
    stopFill: scenario.stopFill,
    boundaryDate: fields.boundaryDate,
    keepDaily: fields.keepDaily ?? false,
    meta: fields.meta
  };
};

// A specification at an arbitrary per-side cost (the parity controls at 0/2/10 bps), otherwise the base conventions.
export const atCost = (spec: Spec, costBps: number): Spec => ({
  ...spec,
  key: `${spec.key}@${costBps}bps`,
  scenario: `cost-${costBps}`,
  costBps,
  rate: base.rate,
  stopSlippageBps: 0,
  stopFill: 'stop'
});

// ----- one-at-a-time (the prior audit's points: v − m, v − s, v + s, v + m per parameter) -----

export interface OatPoint {
  phenotype: string;
  key: (typeof d1Keys)[number];
  offset: OffsetLabel;
  frozen: number;
  value: number;
  distance: number;
  rule: string;
  feasible: boolean;
  reason: string;
  insideSourceBox: boolean; // inside the source study's narrower search box (src/multi-etf-d1/space.ts)
  relativeShift: number; // (value − frozen) ÷ frozen (NaN at a frozen value of 0)
}

export const insideSourceBox = (key: (typeof d1Keys)[number], value: number) => {
  const spec = sourceBox.find((item) => item.key === key);

  return !spec || (value >= spec.min && value <= spec.max);
};

export const oatPointsOf = (phenotype: Phenotype): OatPoint[] =>
  d1Keys.flatMap((key) => {
    const v = phenotype.grid[key];
    const { small, moderate, rule } = distancesOf(key, v);
    const { min, max } = legal(key);

    return offsetLabels.map((offset) => {
      const distance = offset.endsWith('m') ? moderate : small;
      const value = v + (offset.startsWith('-') ? -distance : distance);
      const feasible = value >= min && value <= max;

      return {
        phenotype: phenotype.id,
        key,
        offset,
        frozen: v,
        value,
        distance,
        rule,
        feasible,
        insideSourceBox: insideSourceBox(key, value),
        relativeShift: v !== 0 ? (value - v) / v : NaN,
        reason: feasible
          ? ''
          : `${value < min ? 'below' : 'above'} the engine grid ${value < min ? `minimum ${min}` : `maximum ${max}`} (truncated: not run, not replaced, no boundary probe)`
      };
    });
  });

// ----- joint eight-dimensional neighbourhoods (the prior Latin hypercube over [v − m, v + m] ∩ legal grid, drawn
// from one common stream for every phenotype: common random numbers) -----

export const jointDesignOf = (phenotype: Phenotype, seed: number) => {
  const book: BookSpec = { symbol: phenotype.symbol, phenotype: phenotype.id, grid: { ...phenotype.grid } };
  const dimensions = dimensionsOf([book], phenotype.symbol);
  const samples = latinHypercube(dimensions, jointSamples, ...jointStream, seed);

  return {
    label: [...jointStream, seed].join(' / '),
    dimensions,
    samples: samples.map((values) => {
      const grid = { ...phenotype.grid };

      dimensions.forEach((dimension, index) => {
        grid[dimension.key] = values[index]!;
      });

      return grid;
    })
  };
};

// ----- the run list of one phenotype on its authorized window (PROTOCOL.md §6, §8) -----

export const phenotypeSpecs = (phenotype: Phenotype): Spec[] => {
  const specs: Spec[] = [];
  const subject = phenotype.id;
  const book = bookOf(phenotype);

  for (const scenario of costScenarios) {
    for (const mode of modes) {
      specs.push(
        specOf({
          key: `${scenario.id === 'base' ? 'base' : 'cost'}:${subject}:${scenario.id}:${mode}`,
          family: scenario.id === 'base' ? 'base' : 'cost',
          subject,
          window: 'final',
          mode,
          books: [book],
          scenario,
          keepDaily: scenario.id === 'base',
          meta: { scenario: scenario.id }
        })
      );
    }
  }

  for (const point of oatPointsOf(phenotype)) {
    if (!point.feasible) {
      continue;
    }

    for (const mode of modes) {
      specs.push(
        specOf({
          key: `oat:${subject}:${point.key}:${point.offset}:${mode}`,
          family: 'oat',
          subject,
          window: 'final',
          mode,
          books: [bookOf(phenotype, { ...phenotype.grid, [point.key]: point.value })],
          meta: { parameter: point.key, offset: point.offset, value: point.value }
        })
      );
    }
  }

  for (const seed of jointSeeds) {
    jointDesignOf(phenotype, seed).samples.forEach((grid, index) => {
      for (const mode of modes) {
        specs.push(
          specOf({
            key: `joint:${subject}:s${seed}:${String(index).padStart(2, '0')}:${mode}`,
            family: 'joint',
            subject,
            window: 'final',
            mode,
            books: [bookOf(phenotype, grid)],
            meta: { seed, sample: index }
          })
        );
      }
    });
  }

  return specs;
};

// The unchanged incumbents on the common 2016-01-04 → 2023-12-29 window: B4, B5 under every cost scenario (fixed
// and portfolio) and C0 (portfolio). VGT primary is a phenotype (phenotypeSpecs). Books in the pools' own order.
export const incumbentSpecs = (pools: Record<'B4' | 'B5', Book[]>): Spec[] => {
  const specs: Spec[] = [
    specOf({
      key: 'incumbent:C0:base:portfolio',
      family: 'incumbent',
      subject: 'C0',
      window: 'final',
      mode: 'portfolio',
      books: [],
      keepDaily: true,
      meta: { scenario: 'base' }
    })
  ];

  for (const id of ['B4', 'B5'] as const) {
    for (const scenario of costScenarios) {
      for (const mode of modes) {
        specs.push(
          specOf({
            key: `incumbent:${id}:${scenario.id}:${mode}`,
            family: 'incumbent',
            subject: id,
            window: 'final',
            mode,
            books: pools[id],
            scenario,
            keepDaily: scenario.id === 'base',
            meta: { scenario: scenario.id }
          })
        );
      }
    }
  }

  return specs;
};

export const assertUniqueKeys = (specs: readonly Spec[]) => {
  const keys = new Set<string>();

  for (const spec of specs) {
    if (keys.has(spec.key)) {
      throw new Error(`duplicate run key ${spec.key}`);
    }

    keys.add(spec.key);
  }
};

export type { Family };
